import type { AssetMeta } from "./types.ts";

/**
 * Sticker packs: one character × colorways × reactions.
 * Metadata lives here; artwork lives in `assets/svg/packs/<pack>/<slug>.svg`
 * (generated by `npm run art:packs`, and safe to redraw by hand).
 */

export interface Colorway {
  id: string;
  name: string;
  /** Swatch for pickers. */
  swatch: string;
}

export interface Reaction {
  id: "happy" | "love" | "sad" | "blush";
  name: string;
  tags: readonly string[];
}

export interface PackDefinition {
  id: string;
  name: string;
  species: string;
  description: string;
  colorways: readonly Colorway[];
  reactions: readonly Reaction[];
}

export const REACTIONS: readonly Reaction[] = [
  { id: "happy", name: "Happy", tags: ["happy", "smile", "hello"] },
  { id: "love", name: "Love", tags: ["love", "heart", "crush"] },
  { id: "sad", name: "Sad", tags: ["sad", "cry", "tear", "miss you"] },
  { id: "blush", name: "Blush", tags: ["blush", "shy", "cute", "flattered"] },
];

export const PACKS: readonly PackDefinition[] = [
  {
    id: "miso",
    name: "Miso",
    species: "Cat",
    description: "A round, expressive cat in four colorways.",
    colorways: [
      { id: "ginger", name: "Ginger", swatch: "#FFA43B" },
      { id: "silver", name: "Silver", swatch: "#D9DCE4" },
      { id: "gold", name: "Golden glow", swatch: "#FFD45C" },
      { id: "mist", name: "Mist", swatch: "#4D6699" },
    ],
    reactions: REACTIONS,
  },
  {
    id: "boo",
    name: "Boo",
    species: "Ghost",
    description: "A soft little ghost who feels everything.",
    colorways: [
      { id: "cloud", name: "Cloud", swatch: "#F4F2F6" },
      { id: "moon", name: "Moonlight", swatch: "#D6CCF7" },
    ],
    reactions: REACTIONS,
  },
];

export function packSlug(pack: PackDefinition, colorway: Colorway, reaction: Reaction): string {
  return `${pack.id}-${colorway.id}-${reaction.id}`;
}

export function findPack(id: string | undefined): PackDefinition | undefined {
  return PACKS.find((pack) => pack.id === id);
}

/** Expands every pack into catalogue entries. */
export function expandPacks(): AssetMeta[] {
  return PACKS.flatMap((pack) =>
    pack.colorways.flatMap((colorway) =>
      pack.reactions.map((reaction): AssetMeta => {
        const slug = packSlug(pack, colorway, reaction);
        return {
          id: `sticker-${slug}`,
          slug,
          title: `${pack.name} ${reaction.name}`,
          family: "charm",
          subject: "character",
          description: `${pack.name} the ${pack.species.toLowerCase()}, ${colorway.name.toLowerCase()}, feeling ${reaction.name.toLowerCase()}.`,
          tags: ["sticker", "reaction", pack.species.toLowerCase(), colorway.name.toLowerCase(), ...reaction.tags],
          palette: ["ink"],
          traits: { character: pack.name, pose: "peeking", expression: reaction.id },
          pack: { id: pack.id, colorway: colorway.id, reaction: reaction.id },
          recolorable: false,
          preview: { tone: "cream" },
          relatedAssetIds: pack.reactions
            .filter((other) => other.id !== reaction.id)
            .map((other) => `sticker-${packSlug(pack, colorway, other)}`),
          exports: ["svg", "react", "flutter"],
          status: "available",
          isNew: true,
        };
      }),
    ),
  );
}
